reference_solution:
def count_inverse_pair_arrays(n, k):
    mod = 1_000_000_007
    counts = [1] + [0] * k
    for size in range(1, n + 1):
        prefix = [0]
        for ways in counts:
            prefix.append((prefix[-1] + ways) % mod)
        counts = [(prefix[inversions + 1] - prefix[max(0, inversions - size + 1)]) % mod
                  for inversions in range(k + 1)]
    return counts[k]

